mapper.select:
SELECT A.TXTYPE_TYPE1_NAME, A.TXTYPE_TYPE2_NAME, B.MSGCTL_MSGID, B.MSGCTL_MSG_NAME, B.MSGCTL_CBS_PROC, CASE B.MSGCTL_CBS_PROC WHEN 'Y' THEN 'IMS' WHEN 'N' THEN 'FEP' ELSE '異常'END AS MSGCTL_CBS_PROC_NAME FROM TXTYPE AS A LEFT JOIN MSGCTL AS B ON A.TXTYPE_TYPE1 = B.MSGCTL_TXTYPE1 AND A.TXTYPE_TYPE2 = B.MSGCTL_TXTYPE2 WHERE B.MSGCTL_MSGID NOT IN ('', 'FC2', 'FCA', 'LF', 'LF-2566','216000') AND B.MSGCTL_CHANNEL IN ('ATM', 'FISC') AND B.MSGCTL_CBS_PROC IN ('Y','N')
AND A.TXTYPE_TYPE1 = #{argsMap.uiTxType1, jdbcType=VARCHAR}
AND A.TXTYPE_TYPE2 = #{argsMap.uiTxType2, jdbcType=VARCHAR}
AND B.MSGCTL_CBS_PROC = #{argsMap.uiProcType, jdbcType=VARCHAR}
AND B.MSGCTL_MSGID like CONCAT('%', CONCAT(UPPER(#{argsMap.msgctlMsgid}), '%'))
ORDER BY A.TXTYPE_TYPE1,A.TXTYPE_TYPE2,B.MSGCTL_MSGID
